import{_ as a,o,c as e,a3 as r}from"./chunks/framework.CDBtBf5v.js";const u=JSON.parse('{"title":"OPC UA 报文与诊断查看","description":"","frontmatter":{},"headers":[],"relativePath":"guide/protocols/opcua/packet-view.md","filePath":"guide/protocols/opcua/packet-view.md","lastUpdated":1794013948000}'),d={name:"guide/protocols/opcua/packet-view.md"};function i(l,t,n,s,c,p){return o(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="opc-ua-报文与诊断查看" tabindex="-1">OPC UA 报文与诊断查看 <a class="header-anchor" href="#opc-ua-报文与诊断查看" aria-label="Permalink to &quot;OPC UA 报文与诊断查看&quot;">​</a></h1><p>OPC UA 的通信排查使用 <strong>会话与通信日志</strong> 页，记录实际服务调用的摘要。当前未实现原始 UA TCP 二进制报文抓包，因此本页展示会话和服务日志，适用于浏览、读写、订阅和连接问题排查。</p><h2 id="进入方式" tabindex="-1">进入方式 <a class="header-anchor" href="#进入方式" aria-label="Permalink to &quot;进入方式&quot;">​</a></h2><ol><li>选择 OPC UA 设备，启动服务端或客户端连接。</li><li>执行浏览、读取、写入或订阅，让设备产生真实通信。</li><li>进入 <strong>会话与通信日志</strong>，点击 <strong>查询</strong> 刷新记录。</li><li>按服务名称过滤记录，或导出 CSV。</li></ol><blockquote><p>📷 <strong>截图待补：OPC UA 会话与通信日志</strong> — 展示真实会话和 Browse / Read / Write 等服务调用、状态码及耗时。 建议文件名：<code>opcua-diagnostics.png</code></p></blockquote><h2 id="会话与服务调用" tabindex="-1">会话与服务调用 <a class="header-anchor" href="#会话与服务调用" aria-label="Permalink to &quot;会话与服务调用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>用途</th></tr></thead><tbody><tr><td>会话 / Application URI</td><td>识别连接及客户端应用</td></tr><tr><td>用户、状态、原因、时间</td><td>查看会话建立、关闭或失败情况</td></tr><tr><td>服务</td><td>区分 Browse、Read、Write 等实际调用</td></tr><tr><td>NodeId</td><td>定位操作的目标节点</td></tr><tr><td>StatusCode</td><td>判断调用结果及权限、节点或类型错误</td></tr><tr><td>耗时 / ms</td><td>观察调用响应时间</td></tr></tbody></table><p>诊断摘要不记录凭据或变量值；字节收发统计目前不提供。</p><h2 id="常见排查" tabindex="-1">常见排查 <a class="header-anchor" href="#常见排查" aria-label="Permalink to &quot;常见排查&quot;">​</a></h2><ul><li><strong>连接失败</strong>：确认服务端已启动，Endpoint URL 的 IP、端口和路径一致；在运行状态页查看错误。</li><li><strong>节点不存在</strong>：先浏览远端地址空间，核对 NodeId 与命名空间，不要直接沿用其他设备的命名空间索引。</li><li><strong>写入失败</strong>：核对变量的可写权限、值类型、用户角色和模拟规则的外部写入策略。</li><li><strong>订阅没有数据</strong>：确认节点为 Variable，监控模式为 Reporting，订阅已启用，再检查质量码与重连状态。</li><li><strong>历史查询失败</strong>：确认服务端已对该变量启用历史记录，查询范围内有数据；聚合读取需要远端支持。</li></ul><p>返回 <a href="./">协议介绍</a> 或 <a href="./operation.html">操作指南</a>。</p>',11)])])}const g=a(d,[["render",i]]);export{u as __pageData,g as default};
